nodos.preparar:
ip addr add 10.7.2.10/24 dev eth0
echo "ext OK" > /var/www/html/index.html
cat > /etc/nginx/conf.d/admin.conf <<'EOF'
server {
  listen 8080;
  location / { return 200 "admin\n"; }
}
EOF
nginx

ip addr add 10.9.1.10/24 dev eth0
ip addr add 10.9.2.10/24 dev eth1
sysctl -w net.ipv4.ip_forward=0 >/dev/null
mkdir -p /srv/web /srv/metrics
echo "web corporativa OK" > /srv/web/index.html
printf 'node_load1 0.42\n' > /srv/metrics/metrics
cat > /etc/nginx/conf.d/lab.conf <<'EOF'
server {
  listen 10.9.1.10:80;
  root /srv/web;
}
server {
  listen 10.9.2.10:9100;
  root /srv/metrics;
  default_type text/plain;
}
EOF
nginx -t >/dev/null 2>&1 && nginx
